// @name Pomodoro
// @background #f6f1e9
// @refresh 3600
// A pomodoro timer: focus, then a short break, and a long break after a set
// of focus sessions. Tap the ring (or Start) to start, pause and resume; Skip
// goes on to the next phase and Reset puts this one back to its full length
// (hold Reset for a new set). The tabs pick a phase by hand.
//
// The time comes from the clock: the private `timer` field keeps when the
// phase ends and when it was paused, so a restart loses nothing. On a fast
// screen the ring counts every second; on e-paper it shows whole minutes and
// draws once a minute, and again the moment the phase ends.
import { PHASES, PHASE_NAMES, dayKey, settingsOf, readTimer, leftMs, lengthOf, advance, toggle, reset, resetSet, skip, pick } from './timer'

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

// One accent per phase: terracotta for focus, teal and deep blue for breaks.
const THEMES = {
  color: {
    page: 'bg-[#f6f1e9] text-[#2b2522]',
    muted: 'text-[#7a6f66]',
    tab: 'bg-[#ebe3d6] text-[#5c524a] active:bg-[#e0d6c6]',
    button: 'bg-[#ebe3d6] text-[#2b2522] active:bg-[#e0d6c6]',
    track: '#e7dfd2',
    ink: '#2b2522',
    soft: '#7a6f66',
    empty: '#d9cfbf',
    tomato: '#c8432b',
    leaf: '#4d7c3a',
    accents: { focus: '#b8432c', short: '#0f766e', long: '#1f4e89' },
    on: {
      focus: 'bg-[#b8432c] text-white',
      short: 'bg-[#0f766e] text-white',
      long: 'bg-[#1f4e89] text-white',
    },
  },
  high: {
    page: 'bg-white text-black',
    muted: 'text-black',
    tab: 'bg-white text-black border-2 border-black',
    button: 'bg-white text-black border-2 border-black',
    track: '#ffffff',
    ink: '#000000',
    soft: '#000000',
    empty: '#ffffff',
    tomato: '#000000',
    leaf: '#000000',
    accents: { focus: '#000000', short: '#000000', long: '#000000' },
    on: { focus: 'bg-black text-white', short: 'bg-black text-white', long: 'bg-black text-white' },
  },
}

const pad2 = (n) => String(n).padStart(2, '0')

// The ring: time left as an arc that shrinks clockwise from the top, the time
// in the middle, the phase over it and the set's rounds under it.
function Ring({ size, fraction, color, t, high, big, unit, label, task, rounds, done, onClick }) {
  const c = size / 2
  const stroke = Math.round(size * 0.07)
  const r = c - stroke / 2 - 2
  const f = Math.max(0, Math.min(1, fraction))
  const angle = f * 2 * Math.PI
  const x = c + r * Math.sin(angle)
  const y = c - r * Math.cos(angle)
  const arc = f >= 0.9995 ? null : `M ${c} ${c - r} A ${r} ${r} 0 ${angle > Math.PI ? 1 : 0} 1 ${x.toFixed(1)} ${y.toFixed(1)}`
  const dot = size * 0.022
  const dotGap = dot * 3.2
  const dotsX = c - ((rounds - 1) * dotGap) / 2
  const timeSize = size * (unit ? 0.27 : 0.23)
  return (
    <svg className={`w-[${size}px] h-[${size}px] shrink-0`} viewBox={`0 0 ${size} ${size}`} onClick={onClick}>
      {high ? (
        <circle cx={c} cy={c} r={r} fill="none" stroke="#000000" strokeWidth={2} />
      ) : (
        <circle cx={c} cy={c} r={r} fill="none" stroke={t.track} strokeWidth={stroke} />
      )}
      {f > 0 && arc ? <path d={arc} fill="none" stroke={color} strokeWidth={stroke} strokeLinecap="round" /> : null}
      {f >= 0.9995 ? <circle cx={c} cy={c} r={r} fill="none" stroke={color} strokeWidth={stroke} /> : null}
      <text x={c} y={c - size * 0.17} fontSize={size * 0.06} textAnchor="middle" fill={t.soft} fontWeight="bold">
        {label.toUpperCase()}
      </text>
      <text x={c} y={c + timeSize * 0.36} fontSize={timeSize} textAnchor="middle" fill={t.ink} fontWeight="bold">
        {big}
      </text>
      {unit ? (
        <text x={c} y={c + size * 0.17} fontSize={size * 0.06} textAnchor="middle" fill={t.soft}>
          {unit}
        </text>
      ) : null}
      {task ? (
        <text x={c} y={c + size * (unit ? 0.245 : 0.2)} fontSize={size * 0.052} textAnchor="middle" fill={t.ink}>
          {task}
        </text>
      ) : null}
      {Array.from({ length: rounds }, (_, i) => (
        <circle
          cx={dotsX + i * dotGap}
          cy={c + size * 0.31}
          r={dot}
          fill={i < done ? color : high ? '#ffffff' : t.empty}
          stroke={high ? '#000000' : 'none'}
          strokeWidth={high ? 2 : 0}
        />
      ))}
    </svg>
  )
}

// Today's finished focus sessions as tomatoes, the day's goal as empty ones.
function Tomatoes({ count, goal, size, t, high }) {
  const shown = Math.max(goal, Math.min(count, 12))
  const gap = size * 0.3
  const width = shown * size + (shown - 1) * gap
  return (
    <svg className={`w-[${Math.round(width)}px] h-[${Math.round(size)}px]`} viewBox={`0 0 ${width} ${size}`}>
      {Array.from({ length: shown }, (_, i) => {
        const cx = i * (size + gap) + size / 2
        const cy = size * 0.56
        const r = size * 0.42
        const full = i < count
        return (
          <g>
            <circle cx={cx} cy={cy} r={r} fill={full ? t.tomato : high ? '#ffffff' : t.empty} stroke={high ? '#000000' : 'none'} strokeWidth={high ? 2 : 0} />
            {full ? (
              <path
                d={`M ${cx - r * 0.55} ${cy - r * 0.75} L ${cx} ${cy - r * 0.45} L ${cx + r * 0.55} ${cy - r * 0.75} L ${cx + r * 0.1} ${cy - r * 0.9} L ${cx} ${cy - r * 1.25} L ${cx - r * 0.1} ${cy - r * 0.9} Z`}
                fill={high ? '#ffffff' : t.leaf}
              />
            ) : null}
          </g>
        )
      })}
    </svg>
  )
}

const Icon = ({ d, size }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24">
    <path d={d} fill="currentColor" />
  </svg>
)
const PLAY = 'M8 5.5v13a1 1 0 0 0 1.5.9l10.2-6.5a1 1 0 0 0 0-1.7L9.5 4.6A1 1 0 0 0 8 5.5z'
const PAUSE = 'M7 5h3.5v14H7zM13.5 5H17v14h-3.5z'
const SKIP = 'M5 5.5v13a1 1 0 0 0 1.5.9l8.5-6.5a1 1 0 0 0 0-1.7L6.5 4.6A1 1 0 0 0 5 5.5zM16.5 5H19v14h-2.5z'
const RESET = 'M12 4a8 8 0 1 1-7.7 10.2l2.4-.7A5.5 5.5 0 1 0 12 6.5V10L7 5.25 12 .5z'

function save(timer) {
  frameos.setState('timer', timer)
}

export function get(app, context) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  // Sizes are made for 800x480 (and 480x800) and grow or shrink with the canvas.
  const z = Math.max(0.85, Math.min(2.5, Math.min(W, H) / 480, Math.max(W, H) / 800))
  const px = (n) => Math.round(n * z)
  const high = highContrast(app)
  const t = high ? THEMES.high : THEMES.color
  // Whether a change shows at once: before 2026.11.10 the runtime said it as `paper`.
  const fast = app.frame.fast ?? !app.frame.paper

  const settings = settingsOf(app.state)
  const now = Date.now()
  const today = dayKey(new Date(now))
  const stored = readTimer(app.state.timer, today)
  let timer = advance(stored, settings, now)
  if (timer.day !== today) timer = { ...timer, day: today, count: 0 }
  if (JSON.stringify(timer) !== JSON.stringify(stored)) save(timer)

  const left = leftMs(timer, settings, now)
  const length = lengthOf(timer, settings)

  // When to draw again: every second on a fast screen, at each whole minute
  // on e-paper (the minute shown changes then), and always when the phase ends.
  if (timer.status === 'running') {
    const step = fast ? 1000 : 60000
    const untilChange = left % step || step
    frameos.setNextSleep(Math.min(left, untilChange) / 1000 + 0.05)
  }

  // On e-paper whole minutes, rounded up: 24:01 left shows 25 until it is 24.
  const minutes = Math.ceil(left / 60000)
  const seconds = Math.ceil(left / 1000)
  const big = fast ? `${pad2(Math.floor(seconds / 60))}:${pad2(seconds % 60)}` : String(minutes)
  const unit = fast ? '' : minutes === 1 ? 'minute' : 'minutes'
  const color = t.accents[timer.phase]
  const label = timer.status === 'paused' ? 'Paused' : PHASE_NAMES[timer.phase]
  const task = String(app.state.task ?? '').trim()
  // Focus sessions finished in this set, as dots (a skipped one is not).
  const doneInSet = Math.min(timer.inSet, settings.rounds)

  const act = (next) => save(next)
  const startLabel = timer.status === 'running' ? 'Pause' : timer.status === 'paused' ? 'Resume' : 'Start'

  const portrait = H > W * 1.1
  const square = !portrait && W < H * 1.35
  const pad = px(20)
  const tabsH = px(48)
  const buttonsH = px(56)
  const tomatoSize = px(22)
  const ringSize = portrait
    ? Math.min(W - 2 * pad, H - 2 * pad - tabsH - buttonsH - tomatoSize - px(110))
    : square
      ? Math.min(W - 2 * pad, H - 2 * pad - tabsH - buttonsH - tomatoSize - px(56))
      : Math.min(H - 2 * pad, W * 0.5)

  const Tabs = () => (
    <div className={`flex gap-[${px(8)}px] h-[${tabsH}px]`}>
      {PHASES.map((phase) => (
        <div
          className={`flex-1 rounded-[${px(12)}px] flex items-center justify-center text-[${px(17)}px] font-semibold ${phase === timer.phase ? t.on[phase] : t.tab}`}
          onClick={() => act(pick(timer, phase))}
        >
          {PHASE_NAMES[phase]}
        </div>
      ))}
    </div>
  )

  const Buttons = () => (
    <div className={`flex gap-[${px(10)}px] h-[${buttonsH}px]`}>
      <div
        className={`w-[${px(92)}px] rounded-[${px(14)}px] flex items-center justify-center gap-[${px(6)}px] text-[${px(17)}px] font-semibold ${t.button}`}
        onClick={() => act(reset(timer))}
        onLongPress={() => act(resetSet(timer))}
      >
        <Icon d={RESET} size={px(20)} />
        Reset
      </div>
      <div
        className={`flex-1 rounded-[${px(14)}px] flex items-center justify-center gap-[${px(8)}px] text-[${px(22)}px] font-bold ${t.on[timer.phase]}`}
        onClick={() => act(toggle(timer, settings, Date.now()))}
      >
        <Icon d={timer.status === 'running' ? PAUSE : PLAY} size={px(24)} />
        {startLabel}
      </div>
      <div
        className={`w-[${px(92)}px] rounded-[${px(14)}px] flex items-center justify-center gap-[${px(6)}px] text-[${px(17)}px] font-semibold ${t.button}`}
        onClick={() => act(skip(timer, settings, Date.now()))}
      >
        Skip
        <Icon d={SKIP} size={px(20)} />
      </div>
    </div>
  )

  const Today = () => (
    <div className={`flex items-center gap-[${px(12)}px]`}>
      <Tomatoes count={timer.count} goal={settings.goal} size={tomatoSize} t={t} high={high} />
      <span className={`text-[${px(15)}px] ${t.muted}`}>
        {timer.count > settings.goal ? `${timer.count} today` : `${timer.count} of ${settings.goal} today`}
      </span>
    </div>
  )

  const note = timer.note ? <span className={`text-[${px(17)}px] font-semibold`}>{timer.note}</span> : null

  const ring = (
    <Ring
      size={Math.max(120, Math.floor(ringSize))}
      fraction={length > 0 ? left / length : 1}
      color={color}
      t={t}
      high={high}
      big={big}
      unit={unit}
      label={label}
      // Beside the ring in a wide layout, in it otherwise.
      task={portrait || square ? (task.length > 26 ? task.slice(0, 25) + '…' : task) : ''}
      rounds={settings.rounds}
      done={doneInSet}
      onClick={() => act(toggle(timer, settings, Date.now()))}
    />
  )

  if (portrait || square) {
    return (
      <div className={`flex flex-col w-full h-full gap-[${px(14)}px] p-[${pad}px] ${t.page}`}>
        <Tabs />
        <div className="flex-1 min-h-0 flex flex-col items-center justify-center gap-[8px]">
          {ring}
          {note}
        </div>
        <Buttons />
        <div className="flex justify-center">
          <Today />
        </div>
      </div>
    )
  }
  return (
    <div className={`flex w-full h-full gap-[${px(28)}px] p-[${pad}px] items-center ${t.page}`}>
      {ring}
      <div className={`flex-1 min-w-0 h-full flex flex-col justify-between gap-[${px(12)}px]`}>
        <Tabs />
        <div className={`flex flex-col gap-[${px(6)}px]`}>
          <span className={`text-[${px(15)}px] ${t.muted}`}>
            {`Round ${timer.round} of ${settings.rounds}${timer.phase === 'focus' ? '' : ', break'}`}
          </span>
          <span className={`text-[${px(26)}px] font-bold line-clamp-2`}>{task || PHASE_NAMES[timer.phase]}</span>
          {note}
        </div>
        <Buttons />
        <Today />
      </div>
    </div>
  )
}

// Keys and buttons: forward (or space, Enter) starts, pauses and resumes;
// back resets a phase that has begun, and skips one that has not (as do the
// right arrow and N); R resets.
export function onEvent(app, context) {
  const settings = settingsOf(app.state)
  const now = Date.now()
  const timer = advance(readTimer(app.state.timer, dayKey(new Date(now))), settings, now)
  let next = null
  if (context.event === 'forward') next = toggle(timer, settings, now)
  else if (context.event === 'back') next = timer.status === 'idle' ? skip(timer, settings, now) : reset(timer)
  else if (context.event === 'keyDown') {
    const key = String((context.payload && context.payload.key) || '')
    if (key === ' ' || key === 'Enter') next = toggle(timer, settings, now)
    else if (key === 'ArrowRight' || key === 'n' || key === 'N') next = skip(timer, settings, now)
    else if (key === 'r' || key === 'R') next = reset(timer)
  }
  if (!next) return false
  save(next)
  return true
}

