// The timer, worked out from the clock: what is kept is when the phase ends
// (endAt) and, while paused, when it was paused (pausedAt). Renders are never
// counted, so a late render or a restart loses no time.
//
// timer = {
//   phase: 'focus' | 'short' | 'long',
//   round: the focus session of the set this phase belongs to (1..rounds),
//   status: 'idle' | 'running' | 'paused',
//   endAt, pausedAt, lengthMs: while running or paused,
//   note: what just happened, shown until the next start ('' for nothing),
//   inSet: focus sessions finished in this set (the dots),
//   day: 'YYYY-MM-DD', count: focus sessions finished that day,
// }

export const PHASES = ['focus', 'short', 'long']
export const PHASE_NAMES = { focus: 'Focus', short: 'Short break', long: 'Long break' }

export const dayKey = (date) =>
  `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`

const numberOf = (value, fallback) => {
  const n = Number(value)
  return Number.isFinite(n) && n > 0 ? n : fallback
}
const flag = (value, fallback) => (value === undefined || value === null || value === '' ? fallback : value === true || value === 'true')

// The scene's settings, read once.
export function settingsOf(state) {
  return {
    focus: Math.min(240, numberOf(state.focusMinutes, 25)) * 60000,
    short: Math.min(120, numberOf(state.shortBreakMinutes, 5)) * 60000,
    long: Math.min(240, numberOf(state.longBreakMinutes, 15)) * 60000,
    rounds: Math.max(1, Math.min(12, Math.floor(numberOf(state.rounds, 4)))),
    autoStart: flag(state.autoStart, false),
    goal: Math.max(1, Math.min(24, Math.floor(numberOf(state.dailyGoal, 8)))),
  }
}

export function readTimer(value, today) {
  let timer = value
  if (typeof timer === 'string') {
    try {
      timer = JSON.parse(timer)
    } catch (e) {
      timer = null
    }
  }
  if (!timer || typeof timer !== 'object') timer = {}
  const result = {
    phase: PHASES.includes(timer.phase) ? timer.phase : 'focus',
    round: Math.max(1, Math.floor(Number(timer.round) || 1)),
    status: ['idle', 'running', 'paused'].includes(timer.status) ? timer.status : 'idle',
    endAt: Number(timer.endAt) || 0,
    pausedAt: Number(timer.pausedAt) || 0,
    lengthMs: Number(timer.lengthMs) || 0,
    note: typeof timer.note === 'string' ? timer.note : '',
    day: typeof timer.day === 'string' ? timer.day : today,
    count: Math.max(0, Math.floor(Number(timer.count) || 0)),
    inSet: Math.max(0, Math.floor(Number(timer.inSet) || 0)),
  }
  if (result.status !== 'idle' && (!result.endAt || !result.lengthMs)) result.status = 'idle'
  return result
}

// The milliseconds left in the phase at `now`.
export function leftMs(timer, settings, now) {
  if (timer.status === 'running') return Math.max(0, timer.endAt - now)
  if (timer.status === 'paused') return Math.max(0, timer.endAt - timer.pausedAt)
  return settings[timer.phase]
}

export const lengthOf = (timer, settings) => (timer.status === 'idle' ? settings[timer.phase] : timer.lengthMs)

// A finished focus session counts for the day it finished on.
function countSession(timer, finishedAt) {
  const day = dayKey(new Date(finishedAt))
  const inSet = timer.inSet + 1
  if (day === timer.day) return { ...timer, count: timer.count + 1, inSet }
  return { ...timer, day, count: 1, inSet }
}

// The phase after this one, and its round.
function following(timer, settings) {
  if (timer.phase === 'focus') return { phase: timer.round % settings.rounds === 0 ? 'long' : 'short', round: timer.round }
  if (timer.phase === 'long') return { phase: 'focus', round: 1, inSet: 0 }
  return { phase: 'focus', round: (timer.round % settings.rounds) + 1 }
}

const NOTES = {
  focus: 'Focus session done. Time for a break.',
  short: 'Break over. Ready for the next one?',
  long: 'Set done. Start again when you are ready.',
}

// Every phase that ended since the last look. With auto-start the next phase
// starts the moment the last one ended (its time is counted from then), up
// to the end of a set: after a long break the timer waits for a tap.
export function advance(timer, settings, now) {
  let next = timer
  for (let guard = 0; next.status === 'running' && now >= next.endAt && guard < 48; guard++) {
    const endedAt = next.endAt
    const ended = next.phase
    if (ended === 'focus') next = countSession(next, endedAt)
    const after = following(next, settings)
    if (settings.autoStart && ended !== 'long') {
      const length = settings[after.phase]
      next = { ...next, ...after, status: 'running', endAt: endedAt + length, lengthMs: length, pausedAt: 0, note: '' }
    } else {
      next = { ...next, ...after, status: 'idle', endAt: 0, pausedAt: 0, lengthMs: 0, note: NOTES[ended] }
    }
  }
  if (next.status === 'running' && now >= next.endAt) next = { ...next, status: 'idle', endAt: 0, lengthMs: 0 }
  return next
}

// Start, pause or resume.
export function toggle(timer, settings, now) {
  if (timer.status === 'running') return { ...timer, status: 'paused', pausedAt: now }
  if (timer.status === 'paused') return { ...timer, status: 'running', endAt: timer.endAt + (now - timer.pausedAt), pausedAt: 0 }
  const length = settings[timer.phase]
  return { ...timer, status: 'running', endAt: now + length, lengthMs: length, pausedAt: 0, note: '' }
}

// The phase back to its full length, waiting for a start.
export const reset = (timer) => ({ ...timer, status: 'idle', endAt: 0, pausedAt: 0, lengthMs: 0, note: '' })

// A new set: round one's focus.
export const resetSet = (timer) => ({ ...reset(timer), phase: 'focus', round: 1, inSet: 0 })

// On to the next phase without counting this one. A running timer keeps
// running into it when auto-start is on.
export function skip(timer, settings, now) {
  const after = following(timer, settings)
  const next = { ...reset(timer), ...after }
  return timer.status === 'running' && settings.autoStart ? toggle(next, settings, now) : next
}

// A phase picked by hand: it waits for a start. A focus picked after a long
// break starts a new set.
export function pick(timer, phase) {
  if (phase === timer.phase && timer.status === 'idle') return timer
  if (phase === 'focus' && timer.phase === 'long') return { ...reset(timer), phase, round: 1, inSet: 0 }
  return { ...reset(timer), phase }
}
